package com.ilp.marks;

import java.util.*;

// Checks.java: the trainer's helper. Students do NOT edit this file.
// It tests each step and tells the web page which steps are done.
public class Checks {
    public static final int TOTAL = 10;
    public static final String[] TITLES = { "Page title", "Name input box", "Marks input box", "Add button", "Show each student in the list", "Total marks", "Grade with if / else", "Find the topper", "Delete a student", "Footer with your name" };
    public static final String[] FILES = { "Step01Header.java", "Step02NameBox.java", "Step03MarksBox.java", "Step04AddButton.java", "Step05ShowList.java", "Step06Total.java", "Step07Grade.java", "Step08Topper.java", "Step09Delete.java", "Step10Footer.java" };
    public static final int[] DAYS = { 2, 2, 2, 2, 2, 2, 2, 2, 2, 2 };

    // Returns "done", "todo" or "error: message"
    public static String status(int n) {
        try {
            return test(n) ? "done" : "todo";
        } catch (Throwable e) {
            return "error: " + e.getClass().getSimpleName() + (e.getMessage() == null ? "" : ": " + e.getMessage());
        }
    }

    public static boolean done(int n) {
        return status(n).equals("done");
    }

    public static int doneCount() {
        int c = 0;
        for (int n = 1; n <= TOTAL; n++) if (done(n)) c++;
        return c;
    }

    static boolean test(int n) {
        switch (n) {
            case 1: return String.valueOf(Step01Header.header()).contains("<h1");
            case 2: return String.valueOf(Step02NameBox.nameBox()).contains("name=\"name\"");
            case 3: return String.valueOf(Step03MarksBox.marksBox()).contains("name=\"marks\"");
            case 4: return String.valueOf(Step04AddButton.addButton()).contains("<button");
            case 5: return String.valueOf(Step05ShowList.studentRow(new Student("Ravi", 90))).contains("Ravi");
            case 6: return Step06Total.totalMarks(List.of(new Student("A", 50), new Student("B", 70))) == 120;
            case 7: return Step07Grade.grade(95).equals("A") && Step07Grade.grade(80).equals("B") && Step07Grade.grade(65).equals("C");
            case 8: return Step08Topper.topper(List.of(new Student("A", 50), new Student("B", 90), new Student("C", 70))).name.equals("B");
            case 9: return Checks.deleteWorks();
            case 10: return String.valueOf(Step10Footer.footer()).contains("<footer");
            default: return false;
        }
    }

    static boolean deleteWorks() {
        List<Student> list = new ArrayList<>(List.of(new Student("A", 1), new Student("B", 2), new Student("C", 3)));
        Step09Delete.deleteStudent(list, 1);
        return list.size() == 2 && list.get(1).name.equals("C");
    }
}
